-- VaultFlow gateway-core — 001_init.sql (Phase 0 frozen DDL, source: ARCHITECTURE.md §6.3)
-- Generated by Phase-0 contract-freeze subagent SA-3.
--
-- Faithful transcription of the 18-table ER model (§6.3), §5.1–5.4 state-machine
-- CHECK enums, §6.1 fourteen-account CHECK + non-negative invariant, §6.2 nine
-- closed posting-template reference_type CHECK, all specified partial unique
-- indexes, and the deferred double-entry SUM(DEBIT)=SUM(CREDIT) + balance_after
-- chain-consistency trigger (P0-3).
--
-- Target: PostgreSQL 16. After Phase-0 freeze, change only via new forward
-- migrations — never edit this file in place.

BEGIN;

-- ============================================================================
-- 1. CHAIN_SYNC_CURSORS — one row per chain; the single-writer indexer holds
--    pg_try_advisory_lock(chain_id) and persists the head here (§4.1).
-- ============================================================================
CREATE TABLE chain_sync_cursors (
    chain_id             BIGINT       NOT NULL,
    latest_synced_height BIGINT       NOT NULL DEFAULT 0,
    latest_synced_hash   VARCHAR      NOT NULL DEFAULT '',
    safe_head_height     BIGINT       NOT NULL DEFAULT 0,
    updated_at           TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_chain_sync_cursors PRIMARY KEY (chain_id),
    CONSTRAINT chk_cursors_heights_nonneg
        CHECK (latest_synced_height >= 0 AND safe_head_height >= 0)
);

-- ============================================================================
-- 2. SUPPORTED_ASSETS — whitelisted tokens per chain. Composite PK
--    (chain_id, asset_symbol) is the FK target for orders/payouts.
-- ============================================================================
CREATE TABLE supported_assets (
    chain_id          BIGINT   NOT NULL,
    asset_symbol      VARCHAR  NOT NULL,               -- 'USDT' | 'USDC' | 'ETH'
    token_contract    VARCHAR  NOT NULL,               -- ERC-20 contract address
    decimals          INT      NOT NULL,               -- ETH=18, USDT/USDC=6
    supports_eip3009  BOOLEAN  NOT NULL DEFAULT false,
    CONSTRAINT pk_supported_assets PRIMARY KEY (chain_id, asset_symbol),
    CONSTRAINT uq_supported_assets_contract UNIQUE (chain_id, token_contract),
    CONSTRAINT chk_supported_assets_symbol
        CHECK (asset_symbol IN ('USDT', 'USDC', 'ETH')),
    CONSTRAINT chk_supported_assets_decimals CHECK (decimals >= 0)
);

-- ============================================================================
-- 3. MERCHANTS
-- ============================================================================
CREATE TABLE merchants (
    id                 UUID         NOT NULL DEFAULT gen_random_uuid(),
    name               VARCHAR      NOT NULL,
    api_key_hash       VARCHAR      NOT NULL,
    webhook_url        VARCHAR,
    webhook_secret_enc VARCHAR,
    fee_rate_bps       INT          NOT NULL DEFAULT 0,
    payout_frozen      BOOLEAN      NOT NULL DEFAULT false, -- set when MERCHANT_REORG_RECEIVABLE > 0; cleared by admin review (§4.3)
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_merchants PRIMARY KEY (id),
    CONSTRAINT uq_merchants_api_key_hash UNIQUE (api_key_hash),
    CONSTRAINT chk_merchants_fee_rate CHECK (fee_rate_bps >= 0)
);

-- System sentinel merchant (§6.3 "系统级账户用全零哨兵 UUID" / P0-1):
-- ledger_accounts.owner_merchant_id of platform-level accounts references this
-- all-zero UUID row; it cannot log in (sentinel api_key_hash, no webhook).
INSERT INTO merchants (id, name, api_key_hash, fee_rate_bps)
VALUES ('00000000-0000-0000-0000-000000000000',
        '__SYSTEM__', '__SYSTEM_SENTINEL_NO_API_KEY__', 0);

-- ============================================================================
-- 4. MERCHANT_WITHDRAWAL_ADDRESSES — Ed25519-leased payout whitelist
--    (registration carries the 69B admin lease signature, §1.2 / proto).
-- ============================================================================
CREATE TABLE merchant_withdrawal_addresses (
    id                 UUID         NOT NULL DEFAULT gen_random_uuid(),
    merchant_id        UUID         NOT NULL,
    chain_id           BIGINT       NOT NULL,
    address            VARCHAR      NOT NULL,
    admin_approval_sig BYTEA        NOT NULL,    -- offline admin Ed25519 lease signature
    valid_until        TIMESTAMPTZ  NOT NULL,    -- lease expiry enforced by signer clock
    status             VARCHAR      NOT NULL DEFAULT 'PENDING_COOLDOWN',
    CONSTRAINT pk_merchant_withdrawal_addresses PRIMARY KEY (id),
    CONSTRAINT fk_mwa_merchant FOREIGN KEY (merchant_id) REFERENCES merchants (id),
    CONSTRAINT uq_mwa_merchant_chain_addr UNIQUE (merchant_id, chain_id, address),
    CONSTRAINT chk_mwa_status CHECK (status IN
        ('PENDING_COOLDOWN', 'ACTIVE', 'EXPIRED', 'REVOKED'))
);

-- ============================================================================
-- 5. DEPOSIT_ADDRESSES — CREATE2-derived per-order vault addresses (§2.1).
--    salt = keccak256(chainId, merchantId, orderId); never reused across orders.
-- ============================================================================
CREATE TABLE deposit_addresses (
    id             UUID         NOT NULL DEFAULT gen_random_uuid(),
    chain_id       BIGINT       NOT NULL,
    address        VARCHAR      NOT NULL,          -- predicted CREATE2 address
    create2_salt   BYTEA        NOT NULL,          -- 32B salt
    is_deployed    BOOLEAN      NOT NULL DEFAULT false, -- EIP-1167 proxy lazily deployed by BatchSweeper
    is_quarantined BOOLEAN      NOT NULL DEFAULT false, -- set on VaultQuarantined (blacklist/revert)
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_deposit_addresses PRIMARY KEY (id),
    CONSTRAINT uq_deposit_addresses_chain_addr UNIQUE (chain_id, address),
    CONSTRAINT uq_deposit_addresses_chain_salt UNIQUE (chain_id, create2_salt)
);

-- ============================================================================
-- 6. PAYMENT_ORDERS — 11-state business order machine (§5.2 CHECK lock).
-- ============================================================================
CREATE TABLE payment_orders (
    id                 UUID          NOT NULL DEFAULT gen_random_uuid(),
    merchant_id        UUID          NOT NULL,
    idempotency_key    VARCHAR       NOT NULL,
    request_hash       VARCHAR       NOT NULL,   -- request-body hash for 409 idempotency check (W5-1)
    chain_id           BIGINT        NOT NULL,
    asset_symbol       VARCHAR       NOT NULL,
    expected_amount    NUMERIC(78,0) NOT NULL,
    received_amount    NUMERIC(78,0) NOT NULL DEFAULT 0, -- same-asset FINALIZED deposits only
    deposit_address_id UUID          NOT NULL,   -- strict 1:1 dedicated address
    status             VARCHAR       NOT NULL DEFAULT 'AWAITING_PAYMENT',
    expires_at         TIMESTAMPTZ   NOT NULL,
    settled_at         TIMESTAMPTZ,
    CONSTRAINT pk_payment_orders PRIMARY KEY (id),
    CONSTRAINT fk_orders_merchant FOREIGN KEY (merchant_id)
        REFERENCES merchants (id),
    CONSTRAINT fk_orders_asset FOREIGN KEY (chain_id, asset_symbol)
        REFERENCES supported_assets (chain_id, asset_symbol),
    CONSTRAINT fk_orders_deposit_addr FOREIGN KEY (deposit_address_id)
        REFERENCES deposit_addresses (id),
    CONSTRAINT uq_orders_merchant_idem UNIQUE (merchant_id, idempotency_key),
    CONSTRAINT uq_orders_deposit_addr UNIQUE (deposit_address_id), -- 1:1 binding
    CONSTRAINT chk_orders_status CHECK (status IN
        ('AWAITING_PAYMENT', 'PARTIALLY_PAID', 'PAID', 'OVERPAID', 'EXPIRED',
         'UNDERPAID_EXPIRED_REVIEW', 'LATE_PAID_REVIEW', 'REFUND_IN_PROGRESS',
         'REFUNDED', 'SETTLED_REVERSED', 'REVERSAL_RESOLVED')),
    CONSTRAINT chk_orders_amounts
        CHECK (expected_amount > 0 AND received_amount >= 0)
);

-- ============================================================================
-- 7. CHAIN_BLOCKS — per-chain fork tracking (§4.3 LIFO rollback).
-- ============================================================================
CREATE TABLE chain_blocks (
    chain_id     BIGINT       NOT NULL,
    block_hash   VARCHAR      NOT NULL,
    block_number BIGINT       NOT NULL,
    parent_hash  VARCHAR      NOT NULL,
    status       VARCHAR      NOT NULL DEFAULT 'CANONICAL',
    indexed_at   TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_chain_blocks PRIMARY KEY (chain_id, block_hash),
    CONSTRAINT fk_blocks_cursor FOREIGN KEY (chain_id)
        REFERENCES chain_sync_cursors (chain_id),
    CONSTRAINT chk_blocks_status CHECK (status IN ('CANONICAL', 'ORPHANED')),
    CONSTRAINT chk_blocks_number CHECK (block_number >= 0)
);

-- §6.3 partial unique index: at most one CANONICAL block per height per chain;
-- orphaned forks keep their rows without colliding.
CREATE UNIQUE INDEX uq_chain_blocks_canonical_height
    ON chain_blocks (chain_id, block_number)
    WHERE status = 'CANONICAL';

-- ============================================================================
-- 8. ONCHAIN_DEPOSITS — inbound ERC-20 Transfer observations (§5.1, 4-state).
--    Reorg repacking re-enters under a new block_hash (§4.3), hence the 4-col key.
--    to_address is NOT FK'd: treasury deposits (TREASURY_REBALANCE/TOPUP) land on
--    hot-wallet addresses that are not deposit_addresses rows.
-- ============================================================================
CREATE TABLE onchain_deposits (
    id               UUID          NOT NULL DEFAULT gen_random_uuid(),
    chain_id         BIGINT        NOT NULL,
    block_hash       VARCHAR       NOT NULL,
    tx_hash          VARCHAR       NOT NULL,
    log_index        INT           NOT NULL,
    block_number     BIGINT        NOT NULL,
    token_contract   VARCHAR       NOT NULL,
    from_address     VARCHAR       NOT NULL,
    to_address       VARCHAR       NOT NULL,
    amount           NUMERIC(78,0) NOT NULL,
    deposit_category VARCHAR       NOT NULL,
    status           VARCHAR       NOT NULL DEFAULT 'DETECTED',
    matched_order_id UUID,                       -- nullable (§6.3 "可空")
    CONSTRAINT pk_onchain_deposits PRIMARY KEY (id),
    CONSTRAINT fk_deposits_order FOREIGN KEY (matched_order_id)
        REFERENCES payment_orders (id),
    CONSTRAINT uq_deposits_chain_block_log
        UNIQUE (chain_id, block_hash, tx_hash, log_index),
    CONSTRAINT chk_deposits_category CHECK (deposit_category IN
        ('ORDER_MATCH', 'WRONG_ASSET', 'POST_TERMINAL', 'TREASURY_REBALANCE', 'TOPUP')),
    CONSTRAINT chk_deposits_status CHECK (status IN
        ('DETECTED', 'ORPHANED_SHALLOW', 'FINALIZED', 'ORPHANED_DEEP')),
    CONSTRAINT chk_deposits_amount CHECK (amount > 0),
    CONSTRAINT chk_deposits_log_index CHECK (log_index >= 0)
);

-- §6.3 partial unique index: an active (non-orphaned) log is unique per
-- (chain_id, tx_hash, log_index); orphaned copies are excluded so the same
-- transfer repacked on a new fork inserts cleanly.
CREATE UNIQUE INDEX uq_onchain_deposits_active_log
    ON onchain_deposits (chain_id, tx_hash, log_index)
    WHERE status IN ('DETECTED', 'FINALIZED');

-- ============================================================================
-- 9. WALLET_NONCE_CURSORS — persistent per-hot-wallet nonce allocator;
--    SELECT ... FOR UPDATE hands out serial nonces inside the intent txn (§4.2).
-- ============================================================================
CREATE TABLE wallet_nonce_cursors (
    chain_id       BIGINT       NOT NULL,
    wallet_address VARCHAR      NOT NULL,
    next_nonce     BIGINT       NOT NULL DEFAULT 0,
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_wallet_nonce_cursors PRIMARY KEY (chain_id, wallet_address),
    CONSTRAINT chk_nonce_cursor_nonneg CHECK (next_nonce >= 0)
);

-- ============================================================================
-- 10. OUTBOUND_TX_INTENTS — outbound intent state machine (§5.3, 7-state).
--     reference_id is polymorphic by intent_type (sweep_batches.id /
--     merchant_payouts.id / related order or parent intent) — no FK possible.
-- ============================================================================
CREATE TABLE outbound_tx_intents (
    id             UUID         NOT NULL DEFAULT gen_random_uuid(),
    intent_type    VARCHAR      NOT NULL,
    reference_id   UUID         NOT NULL,
    chain_id       BIGINT       NOT NULL,
    wallet_address VARCHAR      NOT NULL,      -- relayer_hot_wallet / payout_hot_wallet
    nonce          BIGINT       NOT NULL,      -- from wallet_nonce_cursors
    status         VARCHAR      NOT NULL DEFAULT 'QUEUED',
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_outbound_tx_intents PRIMARY KEY (id),
    CONSTRAINT uq_intents_wallet_nonce UNIQUE (chain_id, wallet_address, nonce),
    CONSTRAINT chk_intents_type CHECK (intent_type IN
        ('SWEEP_BATCH', 'MERCHANT_PAYOUT', 'EIP3009_RELAY', 'NONCE_GAP_FILLER')),
    CONSTRAINT chk_intents_status CHECK (status IN
        ('QUEUED', 'IN_FLIGHT', 'INCLUDED_PENDING_SAFE', 'CONFIRMED',
         'FAILED_REVERTED', 'CANCELLED_BY_FILLER', 'NONCE_STOLEN_HALT')),
    CONSTRAINT chk_intents_nonce CHECK (nonce >= 0)
);

-- ============================================================================
-- 11. OUTBOUND_TX_ATTEMPTS — broadcast candidates per intent (RBF bumps,
--     DROPPED re-sends, same-nonce GAP_FILLER cancels, §4.3 LIFO resets).
--     block_number/block_hash/receipt_status are NULLable: reset to BROADCASTED
--     clears them so a repacked candidate can re-enter FINALIZED (§4.3).
-- ============================================================================
CREATE TABLE outbound_tx_attempts (
    id                       UUID          NOT NULL DEFAULT gen_random_uuid(),
    intent_id                UUID          NOT NULL,
    attempt_no               INT           NOT NULL,   -- 1, +1 per RBF bump
    attempt_kind             VARCHAR       NOT NULL DEFAULT 'PRIMARY_INTENT',
    chain_id                 BIGINT        NOT NULL,
    tx_hash                  VARCHAR       NOT NULL,
    block_number             BIGINT,
    block_hash               VARCHAR,
    receipt_status           INT,                      -- 1 success / 0 revert
    max_fee_per_gas          NUMERIC(78,0) NOT NULL,
    max_priority_fee_per_gas NUMERIC(78,0) NOT NULL,
    gas_used                 BIGINT,
    effective_gas_price      NUMERIC(78,0),
    status                   VARCHAR       NOT NULL DEFAULT 'BROADCASTED',
    broadcasted_at           TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT pk_outbound_tx_attempts PRIMARY KEY (id),
    CONSTRAINT fk_attempts_intent FOREIGN KEY (intent_id)
        REFERENCES outbound_tx_intents (id),
    CONSTRAINT uq_attempts_chain_txhash UNIQUE (chain_id, tx_hash),
    CONSTRAINT chk_attempts_kind
        CHECK (attempt_kind IN ('PRIMARY_INTENT', 'GAP_FILLER')),
    CONSTRAINT chk_attempts_status CHECK (status IN
        ('BROADCASTED', 'INCLUDED_UNSAFE', 'FINALIZED', 'SUPERSEDED', 'DROPPED')),
    CONSTRAINT chk_attempts_receipt
        CHECK (receipt_status IS NULL OR receipt_status IN (0, 1)),
    CONSTRAINT chk_attempts_no CHECK (attempt_no >= 1),
    CONSTRAINT chk_attempts_gas CHECK (
        max_fee_per_gas >= 0 AND max_priority_fee_per_gas >= 0
        AND (gas_used IS NULL OR gas_used >= 0)
        AND (effective_gas_price IS NULL OR effective_gas_price >= 0))
);

-- §6.3 partial unique index: at most one attempt per intent may sit in an
-- included/finalized state at any time (RBF candidates race; only one mines).
CREATE UNIQUE INDEX uq_attempts_one_included_per_intent
    ON outbound_tx_attempts (intent_id)
    WHERE status IN ('INCLUDED_UNSAFE', 'FINALIZED');

-- ============================================================================
-- 12. SWEEP_BATCHES — fixed-amount batch sweep runs (§2.2, ≤50 items/batch).
-- ============================================================================
CREATE TABLE sweep_batches (
    id                 UUID          NOT NULL DEFAULT gen_random_uuid(),
    chain_id           BIGINT        NOT NULL,
    asset_symbol       VARCHAR       NOT NULL,
    target_cold_wallet VARCHAR       NOT NULL,
    total_swept_amount NUMERIC(78,0) NOT NULL DEFAULT 0,
    status             VARCHAR       NOT NULL DEFAULT 'PENDING',
    created_at         TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT pk_sweep_batches PRIMARY KEY (id),
    CONSTRAINT chk_sweep_batches_status CHECK (status IN
        ('PENDING', 'IN_FLIGHT', 'COMPLETED', 'PARTIAL_QUARANTINED', 'FAILED')),
    CONSTRAINT chk_sweep_batches_amount CHECK (total_swept_amount >= 0)
);

-- ============================================================================
-- 13. SWEEP_BATCH_ITEMS — per-vault exact-amount sweep legs (§2.2).
--     actual_swept_amount is filled after the VaultSwept receipt; NULL until then.
-- ============================================================================
CREATE TABLE sweep_batch_items (
    id                  UUID          NOT NULL DEFAULT gen_random_uuid(),
    batch_id            UUID          NOT NULL,
    deposit_address_id  UUID          NOT NULL,
    exact_sweep_amount  NUMERIC(78,0) NOT NULL,
    actual_swept_amount NUMERIC(78,0),
    item_status         VARCHAR       NOT NULL DEFAULT 'PENDING',
    CONSTRAINT pk_sweep_batch_items PRIMARY KEY (id),
    CONSTRAINT fk_items_batch FOREIGN KEY (batch_id)
        REFERENCES sweep_batches (id),
    CONSTRAINT fk_items_vault FOREIGN KEY (deposit_address_id)
        REFERENCES deposit_addresses (id),
    CONSTRAINT uq_items_batch_vault UNIQUE (batch_id, deposit_address_id),
    CONSTRAINT chk_items_status CHECK (item_status IN
        ('PENDING', 'SWEPT', 'QUARANTINED_REVERT')),
    CONSTRAINT chk_items_amounts CHECK (
        exact_sweep_amount > 0
        AND (actual_swept_amount IS NULL OR actual_swept_amount >= 0))
);

-- ============================================================================
-- 14. MERCHANT_PAYOUTS — merchant withdrawals + customer refunds (§5.4, 5-state).
--     source_account_type pins the debit-side source liability (§5.4 / §6.2 t.8).
-- ============================================================================
CREATE TABLE merchant_payouts (
    id                  UUID          NOT NULL DEFAULT gen_random_uuid(),
    merchant_id         UUID          NOT NULL,
    idempotency_key     VARCHAR       NOT NULL,
    request_hash        VARCHAR       NOT NULL,
    payout_kind         VARCHAR       NOT NULL,
    source_account_type VARCHAR       NOT NULL,
    source_order_id     UUID,                     -- nullable (§6.3 "可空")
    chain_id            BIGINT        NOT NULL,
    asset_symbol        VARCHAR       NOT NULL,
    to_address          VARCHAR       NOT NULL,
    amount              NUMERIC(78,0) NOT NULL,
    retry_seq           INT           NOT NULL DEFAULT 0,
    admin_refund_ticket BYTEA,                    -- 127B Ed25519 RefundTicket (CUSTOMER_REFUND)
    status              VARCHAR       NOT NULL DEFAULT 'LOCKED_QUEUED',
    created_at          TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT pk_merchant_payouts PRIMARY KEY (id),
    CONSTRAINT fk_payouts_merchant FOREIGN KEY (merchant_id)
        REFERENCES merchants (id),
    CONSTRAINT fk_payouts_asset FOREIGN KEY (chain_id, asset_symbol)
        REFERENCES supported_assets (chain_id, asset_symbol),
    CONSTRAINT fk_payouts_order FOREIGN KEY (source_order_id)
        REFERENCES payment_orders (id),
    CONSTRAINT uq_payouts_merchant_idem UNIQUE (merchant_id, idempotency_key),
    CONSTRAINT chk_payouts_kind
        CHECK (payout_kind IN ('WITHDRAWAL', 'CUSTOMER_REFUND')),
    CONSTRAINT chk_payouts_source CHECK (source_account_type IN
        ('MERCHANT_AVAILABLE', 'SUSPENSE_OVERPAY_LIAB',
         'SUSPENSE_REFUNDABLE_LIAB', 'SUSPENSE_UNMATCHED_LIAB')),
    CONSTRAINT chk_payouts_status CHECK (status IN
        ('LOCKED_QUEUED', 'IN_FLIGHT', 'COMPLETED',
         'FAILED_RETRYABLE', 'CANCELLED_UNLOCKED')),
    CONSTRAINT chk_payouts_amount CHECK (amount > 0),
    CONSTRAINT chk_payouts_retry CHECK (retry_seq >= 0)
);

-- ============================================================================
-- 15. WEBHOOK_OUTBOX — transactional outbox for merchant callbacks (§4.1);
--     consumed FOR UPDATE SKIP LOCKED, exponential backoff → DEAD_LETTER.
-- ============================================================================
CREATE TABLE webhook_outbox (
    id            UUID         NOT NULL DEFAULT gen_random_uuid(),
    merchant_id   UUID         NOT NULL,
    event_type    VARCHAR      NOT NULL,
    payload_json  VARCHAR      NOT NULL,
    retry_count   INT          NOT NULL DEFAULT 0,
    next_retry_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    status        VARCHAR      NOT NULL DEFAULT 'PENDING',
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_webhook_outbox PRIMARY KEY (id),
    CONSTRAINT fk_outbox_merchant FOREIGN KEY (merchant_id)
        REFERENCES merchants (id),
    CONSTRAINT chk_outbox_status
        CHECK (status IN ('PENDING', 'DELIVERED', 'DEAD_LETTER')),
    CONSTRAINT chk_outbox_retry CHECK (retry_count >= 0)
);

-- ============================================================================
-- 16. LEDGER_ACCOUNTS — §6.1 closed set of 14 accounts, NUMERIC(78,0), all
--     non-negative. owner_merchant_id = zero-UUID sentinel for platform/system
--     accounts (seeded above); merchant-scoped accounts use the real merchant id.
-- ============================================================================
CREATE TABLE ledger_accounts (
    id                UUID          NOT NULL DEFAULT gen_random_uuid(),
    owner_merchant_id UUID          NOT NULL,
    chain_id          BIGINT        NOT NULL,
    asset_symbol      VARCHAR       NOT NULL,
    account_type      VARCHAR       NOT NULL,
    normal_side       VARCHAR       NOT NULL,
    balance           NUMERIC(78,0) NOT NULL DEFAULT 0,
    CONSTRAINT pk_ledger_accounts PRIMARY KEY (id),
    CONSTRAINT fk_accounts_owner FOREIGN KEY (owner_merchant_id)
        REFERENCES merchants (id),
    CONSTRAINT uq_accounts_scope
        UNIQUE (owner_merchant_id, chain_id, asset_symbol, account_type),
    CONSTRAINT chk_accounts_type CHECK (account_type IN (
        -- §6.1 debit-normal (6)
        'CUSTODY_UNSWEPT', 'CUSTODY_COLD', 'CUSTODY_HOT_PAYOUT',
        'HOT_WALLET_NATIVE', 'GAS_EXPENSE', 'MERCHANT_REORG_RECEIVABLE',
        -- §6.1 credit-normal (8)
        'ORDER_ESCROW_LIAB', 'MERCHANT_AVAILABLE', 'PAYOUT_LOCKED_LIAB',
        'SUSPENSE_OVERPAY_LIAB', 'SUSPENSE_REFUNDABLE_LIAB',
        'SUSPENSE_UNMATCHED_LIAB', 'TREASURY_EQUITY_CAPITAL', 'FEE_REVENUE')),
    CONSTRAINT chk_accounts_side CHECK (normal_side IN ('DEBIT', 'CREDIT')),
    -- §6.1: normal_side is pinned to account_type — the six debit-normal
    -- asset/expense accounts vs the eight credit-normal liability/equity/revenue
    -- accounts cannot be mixed.
    CONSTRAINT chk_accounts_side_type CHECK (
        (normal_side = 'DEBIT' AND account_type IN
            ('CUSTODY_UNSWEPT', 'CUSTODY_COLD', 'CUSTODY_HOT_PAYOUT',
             'HOT_WALLET_NATIVE', 'GAS_EXPENSE', 'MERCHANT_REORG_RECEIVABLE'))
        OR
        (normal_side = 'CREDIT' AND account_type IN
            ('ORDER_ESCROW_LIAB', 'MERCHANT_AVAILABLE', 'PAYOUT_LOCKED_LIAB',
             'SUSPENSE_OVERPAY_LIAB', 'SUSPENSE_REFUNDABLE_LIAB',
             'SUSPENSE_UNMATCHED_LIAB', 'TREASURY_EQUITY_CAPITAL',
             'FEE_REVENUE'))),
    CONSTRAINT chk_accounts_balance_nonneg CHECK (balance >= 0)
);

-- ============================================================================
-- 17. LEDGER_TRANSACTIONS — one balanced posting per business event.
--     reference_type is locked to the nine closed templates of §6.2;
--     (reference_type, reference_id) is the idempotency key.
-- ============================================================================
CREATE TABLE ledger_transactions (
    id             UUID         NOT NULL DEFAULT gen_random_uuid(),
    reference_type VARCHAR      NOT NULL,
    reference_id   VARCHAR      NOT NULL,
    description    VARCHAR,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT pk_ledger_transactions PRIMARY KEY (id),
    CONSTRAINT uq_ledger_txn_ref UNIQUE (reference_type, reference_id),
    CONSTRAINT chk_ledger_txn_reftype CHECK (reference_type IN (
        'TREASURY_TOPUP', 'INTERNAL_TREASURY_REBALANCE', 'DEPOSIT_FINALIZED',
        'ORDER_SETTLE', 'ORDER_SUSPENSE', 'SWEEP_SETTLE', 'GAS_SETTLE',
        'PAYOUT_FLOW', 'REORG_REVERSAL'))
);

-- ============================================================================
-- 18. LEDGER_ENTRIES — double-entry legs. balance_after is the account-balance
--     snapshot taken while holding the account row lock (accounts locked in
--     account_id ASC order, W3-2). Entries are append-only; corrections are new
--     REORG_REVERSAL / counter postings (§6.2 template 9).
-- ============================================================================
CREATE TABLE ledger_entries (
    id             UUID          NOT NULL DEFAULT gen_random_uuid(),
    transaction_id UUID          NOT NULL,
    account_id     UUID          NOT NULL,
    direction      VARCHAR       NOT NULL,
    amount         NUMERIC(78,0) NOT NULL,
    balance_after  NUMERIC(78,0) NOT NULL,
    created_at     TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT pk_ledger_entries PRIMARY KEY (id),
    CONSTRAINT fk_entries_txn FOREIGN KEY (transaction_id)
        REFERENCES ledger_transactions (id),
    CONSTRAINT fk_entries_account FOREIGN KEY (account_id)
        REFERENCES ledger_accounts (id),
    CONSTRAINT chk_entries_direction CHECK (direction IN ('DEBIT', 'CREDIT')),
    CONSTRAINT chk_entries_amount CHECK (amount > 0),
    CONSTRAINT chk_entries_balance_nonneg CHECK (balance_after >= 0)
);

-- ============================================================================
-- Secondary (non-unique) indexes for the hot access paths exercised by the
-- indexer / txmanager / sweeper / webhook workers. These are access-path
-- indexes only; all uniqueness semantics live in the §6.3 constraints above.
-- ============================================================================
CREATE INDEX idx_chain_blocks_height        ON chain_blocks (chain_id, block_number);
CREATE INDEX idx_onchain_deposits_to        ON onchain_deposits (chain_id, to_address);
CREATE INDEX idx_onchain_deposits_order     ON onchain_deposits (matched_order_id);
CREATE INDEX idx_payment_orders_status      ON payment_orders (status);
CREATE INDEX idx_outbound_attempts_intent   ON outbound_tx_attempts (intent_id);
CREATE INDEX idx_outbound_intents_status    ON outbound_tx_intents (status);
CREATE INDEX idx_sweep_items_address        ON sweep_batch_items (deposit_address_id);
CREATE INDEX idx_webhook_outbox_due         ON webhook_outbox (status, next_retry_at);
CREATE INDEX idx_ledger_entries_txn         ON ledger_entries (transaction_id);
CREATE INDEX idx_ledger_entries_account     ON ledger_entries (account_id);
CREATE INDEX idx_merchant_payouts_order     ON merchant_payouts (source_order_id);

-- ============================================================================
-- Double-entry bookkeeping invariant triggers (P0-3 "复式记账借贷平衡校验触发器").
--
-- gateway-core posts a ledger transaction in ONE local ACID transaction:
--   insert ledger_transactions -> lock ledger_accounts ASC FOR UPDATE, update
--   balances -> insert ledger_entries carrying balance_after snapshots -> COMMIT.
-- The checks therefore run DEFERRED at COMMIT, when the whole posting is visible.
-- ============================================================================

-- Append-only guard: posted entries and transaction headers are immutable.
-- Corrections happen exclusively through new counter-postings (§6.2 template 9).
CREATE OR REPLACE FUNCTION fn_ledger_immutable()
RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION '%.% is append-only: % is forbidden — post a REORG_REVERSAL / counter entry instead (ARCHITECTURE.md §6.2)',
        TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_ledger_entries_immutable
    BEFORE UPDATE OR DELETE ON ledger_entries
    FOR EACH ROW EXECUTE FUNCTION fn_ledger_immutable();

CREATE TRIGGER trg_ledger_transactions_immutable
    BEFORE UPDATE OR DELETE ON ledger_transactions
    FOR EACH ROW EXECUTE FUNCTION fn_ledger_immutable();

-- Deferred balance + balance_after consistency check.
--
-- Invariant 1 (trial balance): per ledger_transaction,
--   SUM(amount WHERE direction='DEBIT') = SUM(amount WHERE direction='CREDIT') > 0.
--
-- Invariant 2 (balance_after consistency): for every (transaction_id, account_id)
--   group, the entries must form one ordered chain
--     open -e1-> b1 -e2-> b2 ... -ek-> final,
--   where each entry e maps implied_prev = balance_after -/+ amount (DEBIT adds,
--   CREDIT subtracts). Verified in three steps:
--     a) the bag of implied prevs vs the bag of balance_after values must differ
--        by exactly one element each: a single opening value (prev side) and a
--        single terminal value (after side) — the degree-sequence condition;
--     b) the terminal value must equal ledger_accounts.balance committed in the
--        same transaction (snapshot consistency with the locked account row);
--     c) connectivity: walking unused edges from the opening value must consume
--        all entries and land on the terminal value (rejects disjoint cycles).
--   Note: a posting that revisits an identical pre-balance for the same account
--   within one transaction is inherently ambiguous (no entry sequence column in
--   §6.3) and is rejected by (c); split such postings into separate transactions.
CREATE OR REPLACE FUNCTION fn_ledger_check_txn_balanced()
RETURNS trigger AS $$
DECLARE
    v_debit   NUMERIC(78,0);
    v_credit  NUMERIC(78,0);
    r_acct    RECORD;
    r_edge    RECORD;
    v_srows   INT;
    v_erows   INT;
    v_sdeg    INT;
    v_edeg    INT;
    v_start   NUMERIC(78,0);
    v_end     NUMERIC(78,0);
    v_acctbal NUMERIC(78,0);
    v_total   INT;
    v_cur     NUMERIC(78,0);
    v_steps   INT;
    v_used    UUID[];
BEGIN
    -- (1) Trial balance: SUM(DEBIT) == SUM(CREDIT) per ledger_transaction (§6.2).
    SELECT COALESCE(SUM(amount) FILTER (WHERE direction = 'DEBIT'),  0),
           COALESCE(SUM(amount) FILTER (WHERE direction = 'CREDIT'), 0)
      INTO v_debit, v_credit
      FROM ledger_entries
     WHERE transaction_id = NEW.transaction_id;

    IF v_debit <> v_credit THEN
        RAISE EXCEPTION 'ledger_transaction % violates double-entry balance: SUM(DEBIT)=% <> SUM(CREDIT)=%',
            NEW.transaction_id, v_debit, v_credit;
    END IF;
    IF v_debit <= 0 THEN
        RAISE EXCEPTION 'ledger_transaction % has no entries (empty postings are not allowed)',
            NEW.transaction_id;
    END IF;

    -- (2) balance_after chain consistency per (transaction_id, account_id).
    FOR r_acct IN
        SELECT DISTINCT account_id
          FROM ledger_entries
         WHERE transaction_id = NEW.transaction_id
    LOOP
        -- (2a) bag-difference degree-sequence check:
        --   starts = implied_prev values not consumed as an after (must be {open});
        --   ends   = balance_after values not consumed as a prev (must be {final}).
        WITH prevs AS (
                 SELECT balance_after
                        - CASE direction WHEN 'DEBIT' THEN amount ELSE -amount END AS prev
                   FROM ledger_entries
                  WHERE transaction_id = NEW.transaction_id
                    AND account_id     = r_acct.account_id),
             bgrp AS (SELECT prev, COUNT(*) AS c FROM prevs GROUP BY prev),
             agrp AS (SELECT balance_after AS v, COUNT(*) AS c
                        FROM ledger_entries
                       WHERE transaction_id = NEW.transaction_id
                         AND account_id     = r_acct.account_id
                       GROUP BY balance_after),
             starts AS (
                 SELECT bgrp.prev AS v, bgrp.c - COALESCE(agrp.c, 0) AS d
                   FROM bgrp LEFT JOIN agrp ON agrp.v = bgrp.prev
                  WHERE bgrp.c > COALESCE(agrp.c, 0)),
             ends AS (
                 SELECT agrp.v, agrp.c - COALESCE(bgrp.c, 0) AS d
                   FROM agrp LEFT JOIN bgrp ON bgrp.prev = agrp.v
                  WHERE agrp.c > COALESCE(bgrp.c, 0))
        SELECT (SELECT COUNT(*) FROM starts), (SELECT COUNT(*) FROM ends),
               (SELECT v FROM starts LIMIT 1), (SELECT v FROM ends LIMIT 1),
               (SELECT d FROM starts LIMIT 1), (SELECT d FROM ends LIMIT 1)
          INTO v_srows, v_erows, v_start, v_end, v_sdeg, v_edeg;

        IF v_srows <> 1 OR v_erows <> 1 OR v_sdeg <> 1 OR v_edeg <> 1 THEN
            RAISE EXCEPTION 'ledger_transaction %: balance_after values for account % do not form a single chain (openings=%, terminals=%)',
                NEW.transaction_id, r_acct.account_id, v_srows, v_erows;
        END IF;

        -- (2b) the terminal snapshot must equal the committed account balance.
        SELECT balance INTO v_acctbal
          FROM ledger_accounts
         WHERE id = r_acct.account_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'ledger_entries reference missing ledger_account %',
                r_acct.account_id;
        END IF;
        IF v_end <> v_acctbal THEN
            RAISE EXCEPTION 'ledger_transaction %: terminal balance_after % for account % <> committed ledger_accounts.balance %',
                NEW.transaction_id, v_end, r_acct.account_id, v_acctbal;
        END IF;

        -- (2c) connectivity: walk unused edges from the opening balance; every
        -- entry must be reachable in one chain ending on the terminal value.
        SELECT COUNT(*) INTO v_total
          FROM ledger_entries
         WHERE transaction_id = NEW.transaction_id
           AND account_id     = r_acct.account_id;

        v_used  := ARRAY[]::uuid[];
        v_cur   := v_start;
        v_steps := 0;
        LOOP
            SELECT e.id, e.balance_after
              INTO r_edge
              FROM ledger_entries e
             WHERE e.transaction_id = NEW.transaction_id
               AND e.account_id     = r_acct.account_id
               AND NOT (e.id = ANY (v_used))
               AND e.balance_after
                   - CASE e.direction WHEN 'DEBIT' THEN e.amount ELSE -e.amount END
                   = v_cur
             ORDER BY e.id
             LIMIT 1;
            EXIT WHEN NOT FOUND;
            v_used  := v_used || r_edge.id;
            v_cur   := r_edge.balance_after;
            v_steps := v_steps + 1;
        END LOOP;

        IF v_steps <> v_total THEN
            RAISE EXCEPTION 'ledger_transaction %: balance_after chain for account % is disconnected or ambiguous (% of % entries reachable from opening balance %)',
                NEW.transaction_id, r_acct.account_id, v_steps, v_total, v_start;
        END IF;
        IF v_cur <> v_end THEN
            RAISE EXCEPTION 'ledger_transaction %: balance_after chain for account % ends at %, expected terminal %',
                NEW.transaction_id, r_acct.account_id, v_cur, v_end;
        END IF;
    END LOOP;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- CONSTRAINT TRIGGER … DEFERRABLE INITIALLY DEFERRED: fires once per inserted
-- entry row at COMMIT, when the full posting (header + entries + account balance
-- updates) is visible. Partial postings committed on their own fail invariant 1.
CREATE CONSTRAINT TRIGGER trg_ledger_entries_balanced
    AFTER INSERT ON ledger_entries
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION fn_ledger_check_txn_balanced();

COMMIT;
